#ifndef __TIPTOP_GAMETEXT_H__
#define __TIPTOP_GAMETEXT_H__

// The strings TipTop keeps in its exe (messages, labels, the font's character order) are read from the player's
// own TipTop.exe at start-up, by address: by the user's decision (2026-10-19) no game text is in the repository.
//
// - GameTextTable.inc (generated by games/tiptop/tools/make_gametext.py) lists each string's address in the game
//   image, its length and a hash: no text.
// - LoadGameTexts() finds TipTop.exe in the game folder, reads each string at its address and checks length and
//   hash. A string that does not match (another version of the exe) stays empty and is logged.
// - Code names a string by its address in the original: GT(0x0046c2d0). Overrides: any string property named
//   GT_<8 hex digits> replaces the string read from the exe.

#include <cstdint>

namespace tiptop
{

// Reads the strings from the game folder's executable and applies the string-property overrides. Returns false
// when the executable is missing or no string matched.
bool LoadGameTexts();
// The string the original keeps at theVA; "" for an address that is not in the table
const char* GameText(uint32_t theVA);

} // namespace tiptop

#define GTC(theVA) (::tiptop::GameText(theVA))

#endif
